import { test, expect } from '@playwright/test';

test.describe('Logout Functionality - Standard User', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
    await page.getByLabel('Sign in').click();
    await page.getByLabel('standard_user').fill('standard_user');
    await page.getByLabel('secret_sauce').fill('secret_sauce');
    await page.getByRole('button', { name: /sign in/i }).click();
    await page.waitForURL('**/dashboard');
  });

  test('should log out successfully and return to login page', async ({ page }) => {
    // Verify user is signed in
    const dashboardTitle = page.getByRole('heading', { name: /dashboard/i });
    await expect(dashboardTitle).toBeVisible();

    // Click burger menu button to open side menu
    const burgerMenuBtn = page.getByRole('button', { name: /menu/i });
    await expect(burgerMenuBtn).toBeVisible();
    await burgerMenuBtn.click();

    // Verify side menu is visible
    const sideMenu = page.getByRole('navigation', { name: /side menu/i });
    await expect(sideMenu).toBeVisible();

    // Click logout link
    const logoutLink = page.getByRole('link', { href: /logout/i });
    await expect(logoutLink).toBeVisible();
    await logoutLink.click();

    // Verify user is redirected to login page
    await expect(page).toHaveURL(/login/);

    // Verify login button is visible again
    const loginButton = page.getByRole('button', { name: /sign in/i });
    await expect(loginButton).toBeVisible();
  });

  test('should handle logout failure and display error message', async ({ page }) => {
    // Mock API response for logout failure
    await page.route('**/api/auth/logout', (route) => {
      route.abort('failed');
    });

    // Click burger menu button to open side menu
    const burgerMenuBtn = page.getByRole('button', { name: /menu/i });
    await expect(burgerMenuBtn).toBeVisible();
    await burgerMenuBtn.click();

    // Click logout link
    const logoutLink = page.getByRole('link', { href: /logout/i });
    await expect(logoutLink).toBeVisible();
    await logoutLink.click();

    // Verify error message is displayed
    const errorMessage = page.getByText(/error/i);
    await expect(errorMessage).toBeVisible();

    // Verify login button is still visible
    const loginButton = page.getByRole('button', { name: /sign in/i });
    await expect(loginButton).toBeVisible();
  });
});
